import "./Header.css";
import Bell from '../assets/bell.png';
import Search from '../assets/search.png';
import User from '../assets/user-round.png';
import Logo from '../assets/logo.png';
import { Link, useLocation } from "react-router-dom"; // 딱 이 두개만 필요!

export default function Header() {
  const location = useLocation();

  // 경로명은 App.js와 반드시 일치!
  const menuList = [
    { name: "메인", path: "/" },
    { name: "탐색", path: "/explore" },
    { name: "AI 검색", path: "/aisearch" }, // 소문자 권장!
  ];

  return (
    <header className="custom-header">
      <img src={Logo} alt="서산에 뭐 issue?" className="header-logo" />
      
      <nav className="header-nav">
        {menuList.map(menu => (
          <Link
            key={menu.path}
            to={menu.path}
            className={`header-nav-link${location.pathname === menu.path ? " active" : ""}`}
          >
            {menu.name}
          </Link>
        ))}
      </nav>

      <div className="header-icons">
        <img src={Bell} alt="알림" className="header-icon" />
        <img src={Search} alt="검색" className="header-icon" />
        <img src={User} alt="유저" className="header-icon" />
      </div>
    </header>
  );
}
